/**
 * The producer's three answers — current, stale, missing — plus the build's own
 * contract: a successful build records its reachable inputs, a failed build
 * publishes no current stamp.
 *
 * Reachability is the build's (metafile) answer, so a newly added module enters
 * the set through its importer's changed content: the refusal names that
 * importer, which is what an operator can act on. Nothing here asserts a
 * fingerprint value or compares generated bytes.
 */
import { afterAll, describe, expect, test } from 'bun:test'
import { mkdirSync, mkdtempSync, rmSync, utimesSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { STAMP_FILE, buildHost, checkHostBuild, recordInputStamp } from './build-host.ts'

const scratch: string[] = []
afterAll(() => {
  for (const dir of scratch) rmSync(dir, { recursive: true, force: true })
})

function fixtureRoot(): string {
  const root = mkdtempSync(join(tmpdir(), 'dsh-build-host-'))
  scratch.push(root)
  return root
}

/** A stamped fixture: two sources, one recorded output, no build run. */
function stampedFixture(): string {
  const root = fixtureRoot()
  mkdirSync(join(root, 'src'))
  mkdirSync(join(root, 'dist'))
  writeFileSync(join(root, 'src', 'a.ts'), 'export const a = 1\n')
  writeFileSync(join(root, 'src', 'b.ts'), 'export const b = 2\n')
  writeFileSync(join(root, 'dist', 'index.js'), '')
  recordInputStamp(root, ['src/a.ts', 'src/b.ts'], ['dist/index.js'])
  return root
}

describe('checkHostBuild — source-input freshness', () => {
  test('current: the recorded inputs and outputs are unchanged', () => {
    expect(checkHostBuild(stampedFixture())).toEqual({ state: 'current' })
  })

  test('stale: changed content names the input', () => {
    const root = stampedFixture()
    writeFileSync(join(root, 'src', 'a.ts'), 'export const a = 3\n')
    expect(checkHostBuild(root)).toEqual({ state: 'stale', input: 'src/a.ts' })
  })

  test('current: unchanged content with a changed mtime is not stale', () => {
    const root = stampedFixture()
    const later = new Date(Date.now() + 60 * 60 * 1000)
    utimesSync(join(root, 'src', 'a.ts'), later, later)
    utimesSync(join(root, 'dist', 'index.js'), later, later)
    expect(checkHostBuild(root)).toEqual({ state: 'current' })
  })

  test('missing: a recorded input that vanished names that input', () => {
    const root = stampedFixture()
    rmSync(join(root, 'src', 'b.ts'))
    expect(checkHostBuild(root)).toEqual({ state: 'missing', input: 'src/b.ts' })
  })

  test('missing: a recorded output that vanished names that output', () => {
    const root = stampedFixture()
    rmSync(join(root, 'dist', 'index.js'))
    expect(checkHostBuild(root)).toEqual({ state: 'missing', input: 'dist/index.js' })
  })

  test('missing: no stamp at all (never built) names the stamp', () => {
    const root = fixtureRoot()
    expect(checkHostBuild(root)).toEqual({ state: 'missing', input: STAMP_FILE })
  })

  test('stale: a newly added reachable module names the importer that reached it', () => {
    const root = stampedFixture()
    writeFileSync(join(root, 'src', 'c.ts'), 'export const c = 3\n')
    writeFileSync(join(root, 'src', 'a.ts'), "import { c } from './c.ts'\nexport const a = c\n")
    expect(checkHostBuild(root)).toEqual({ state: 'stale', input: 'src/a.ts' })
  })
})

describe('buildHost — the build owns the stamp', () => {
  /** A buildable fixture root: the two host entrypoints, nothing else. */
  function buildableRoot(): string {
    const root = fixtureRoot()
    mkdirSync(join(root, 'src'))
    writeFileSync(join(root, 'src', 'index.ts'), 'export const host = 1\n')
    writeFileSync(join(root, 'src', 'invariant.ts'), 'export const invariant = 1\n')
    return root
  }

  test('a successful build records the reachable inputs and the check is current', async () => {
    const root = buildableRoot()
    await buildHost(root)
    expect(checkHostBuild(root)).toEqual({ state: 'current' })
    // The entries are reachable by definition; a build that recorded nothing has no stamp.
    const stamp = JSON.parse(await Bun.file(join(root, STAMP_FILE)).text()) as { inputs: Record<string, string> }
    expect(Object.keys(stamp.inputs).sort()).toEqual(['src/index.ts', 'src/invariant.ts'])
  })

  test('a failed build publishes no current stamp', async () => {
    const root = buildableRoot()
    writeFileSync(join(root, 'src', 'index.ts'), 'export const host = ((("\n')
    await expect(buildHost(root)).rejects.toThrow()
    expect(checkHostBuild(root)).toEqual({ state: 'missing', input: STAMP_FILE })
  })
})
